size_t n = boxes.size();
std::vector<std::pair<size_t, size_t>> result;
for (size_t i = 0; i < n; ++i) {
    for (size_t j = i + 1; j < n; ++j) {
        if (boxes[i].Intersects(boxes[j])) {
            result.emplace_back(i, j);
        }
    }
}
return result;

